package kr.yunseok.touchmacro;
import org.junit.Test;
import java.util.*;
import java.io.*;
import static org.junit.Assert.*;
public class BehaviorVisualTest {
 static BehaviorVisual.Frame image(int bg,int x,int y,boolean second){int[] a=new int[1080*1920];Arrays.fill(a,bg);for(int j=y;j<y+48;j++)for(int i=x;i<x+48;i++)a[j*1080+i]=((i-x<12||j-y<12)?0xffe04040:0xff3050e0);if(second)for(int j=y;j<y+48;j++)for(int i=x+400;i<x+448;i++)a[j*1080+i]=((i-x-400<12||j-y<12)?0xffe04040:0xff3050e0);return BehaviorVisual.Frame.fromArgb(1080,1920,a);}
 static BehaviorExample.Observation obs(BehaviorVisual.Frame f,String previous){return new BehaviorExample.Observation(new BehaviorExample.Binding("task","session","demo.app",0,0,0,1,1080,1920),List.of(new BehaviorExample.Token("같은 글자",10,10,100,40,"LINE")),previous,new double[8],f);}
 static BehaviorExample.Replay replay(BehaviorExample.Registry r,BehaviorVisual.Frame a,BehaviorVisual.Frame b){BehaviorExample.Replay replay=new BehaviorExample.Replay();for(int n=0;n<2;n++)for(int k=0;k<2;k++){BehaviorExample.Observation o=obs(k==0?a:b,"");replay=replay.append(new BehaviorExample("row"+n+k,o,r.get(k).id,o,"DEMONSTRATION",null,true,false));}return replay;}
 @Test public void visualResolverCancellationStopsBeforeAnyMatch(){BehaviorVisual.Frame a=image(0xffeeeeee,180,600,false);BehaviorVisual.Patch patch=BehaviorVisual.patchAt(a,204,624,1080,1920);java.util.concurrent.atomic.AtomicInteger calls=new java.util.concurrent.atomic.AtomicInteger();assertThrows(java.util.concurrent.CancellationException.class,()->BehaviorVisual.resolve(a,patch,1080,1920,()->calls.incrementAndGet()>2));assertTrue(calls.get()<5);}
 @Test public void absentIconIsNotReplacedByEmptySpace(){BehaviorVisual.Frame a=image(0xffeeeeee,180,600,false);BehaviorVisual.Patch p=BehaviorVisual.patchAt(a,204,624,1080,1920);int[] pixels=new int[1080*1920];Arrays.fill(pixels,0xffeeeeee);assertThrows(IllegalArgumentException.class,()->BehaviorVisual.resolve(BehaviorVisual.Frame.fromArgb(1080,1920,pixels),p,1080,1920));}
 @Test public void iconTargetSurvivesJsonAndResolutionChange(){BehaviorVisual.Frame original=image(0xffeeeeee,180,600,false);BehaviorVisual.Patch patch=BehaviorVisual.patchAt(original,204,624,1080,1920);try{BehaviorVisual.Patch copy=BehaviorVisual.Patch.fromJson(patch.json());BehaviorVisual.Match a=BehaviorVisual.resolve(image(0xffeeeeee,580,1000,false),copy,2160,3840);assertTrue(Math.abs((a.left+a.right)/2-1208)<60);}catch(Exception e){throw new AssertionError(e);}}
 @Test public void imageActionDoesNotRequireAnyOcrTokens(){BehaviorVisual.Frame visual=image(0xffeeeeee,180,600,false);BehaviorExample.Observation o=obs(visual,"");BehaviorExample.Observation empty=new BehaviorExample.Observation(o.binding,List.of(),"",new double[8],visual);BehaviorVisual.Patch patch=BehaviorVisual.patchAt(visual,204,624,1080,1920);BehaviorExample.Registry registry=new BehaviorExample.Registry().append(new BehaviorExample.Action("icon",BehaviorExample.Type.VISUAL_TAP,null,0,false,patch));BehaviorExample.Replay replay=new BehaviorExample.Replay();for(int i=0;i<2;i++)replay=replay.append(new BehaviorExample("v"+i,empty,"icon",empty,"DEMONSTRATION",null,true,false));assertEquals("icon",BehaviorAndroidSession.supportedAction(replay,"task","demo.app",empty));BehaviorVisual.Match match=BehaviorVisual.resolve(empty.visual,registry.get(0).visualPatch,1080,1920);assertTrue(match.left<204&&match.right>204);}
 @Test public void visualLearningCancellationPreservesOriginalWeights(){BehaviorVisual.Frame a=image(0xff101020,180,600,false),b=image(0xffeeeecc,180,600,false);BehaviorExample.Registry r=new BehaviorExample.Registry().append(new BehaviorExample.Action("a",BehaviorExample.Type.BACK,null,0,false)).append(new BehaviorExample.Action("b",BehaviorExample.Type.FINISH,null,0,false));BehaviorVisualPolicy original=new BehaviorVisualPolicy(2);double[] before=original.parameters();java.util.concurrent.atomic.AtomicInteger calls=new java.util.concurrent.atomic.AtomicInteger();assertThrows(java.util.concurrent.CancellationException.class,()->original.learn(replay(r,a,b),r,"task",128,()->calls.incrementAndGet()>3));assertArrayEquals(before,original.parameters(),0);assertEquals(0,original.completedSteps());}
 @Test public void addingVisualExamplesDoesNotEraseLegacyTextSupport(){BehaviorExample.Registry r=new BehaviorExample.Registry().append(new BehaviorExample.Action("legacy",BehaviorExample.Type.TEXT_TAP,"옛 글자",0,false)).append(new BehaviorExample.Action("new",BehaviorExample.Type.BACK,null,0,false));BehaviorExample.Observation old=BehaviorExampleTest.observation("옛 글자");BehaviorExample.Replay replay=new BehaviorExample.Replay();for(int i=0;i<2;i++)replay=replay.append(new BehaviorExample("old"+i,old,"legacy",old,"DEMONSTRATION",null,true,false));BehaviorVisual.Frame trained=image(0xff101020,180,600,false);for(int i=0;i<2;i++){BehaviorExample.Observation v=obs(trained,"");replay=replay.append(new BehaviorExample("new"+i,v,"new",v,"DEMONSTRATION",null,true,false));}BehaviorExample.Observation current=new BehaviorExample.Observation(old.binding,old.tokens,"",new double[8],image(0xffeeeecc,180,600,false));assertEquals("legacy",BehaviorAndroidSession.supportedAction(replay,"task","demo.app",current));}
 @Test public void visualOnlyDemonstrationsDoNotOverwriteLegacyTextWeights(){BehaviorVisual.Frame a=image(0xff101020,180,600,false),b=image(0xffeeeecc,180,600,false);BehaviorExample.Registry r=new BehaviorExample.Registry().append(new BehaviorExample.Action("a",BehaviorExample.Type.BACK,null,0,false)).append(new BehaviorExample.Action("b",BehaviorExample.Type.FINISH,null,0,false));BehaviorPolicy original=new BehaviorPolicy(2,17),after=original.learn(replay(r,a,b),r,"task",64,8,.05,()->false);assertArrayEquals(original.parameters(),after.parameters(),0);assertEquals(original.completedSteps(),after.completedSteps());}
 @Test public void iconIsFoundAfterProportionalDeviceResolutionChange(){BehaviorVisual.Frame original=image(0xffeeeeee,180,600,false);BehaviorVisual.Patch patch=BehaviorVisual.patchAt(original,204,624,1080,1920);int width=720,height=1280;int[] pixels=new int[width*height];Arrays.fill(pixels,0xffeeeeee);for(int y=400;y<432;y++)for(int x=120;x<152;x++)pixels[y*width+x]=(x<128||y<408)?0xffe04040:0xff3050e0;BehaviorVisual.Match found=BehaviorVisual.resolve(BehaviorVisual.Frame.fromArgb(width,height,pixels),patch,width,height);assertTrue(Math.abs((found.left+found.right)/2-136)<20);assertTrue(Math.abs((found.top+found.bottom)/2-416)<20);}
 @Test public void visualJsonRejectsOversizeAndUnexpectedFields(){BehaviorVisual.Frame visual=image(0xffeeeeee,180,600,false);assertThrows(IllegalArgumentException.class,()->BehaviorVisual.Frame.fromJson(visual.json().put("extra",1)));BehaviorVisual.Patch patch=BehaviorVisual.patchAt(visual,204,624,1080,1920);assertThrows(IllegalArgumentException.class,()->BehaviorVisual.Patch.fromJson(patch.json().put("rgb","A")));assertThrows(IllegalArgumentException.class,()->new BehaviorBundle.Snapshot("task",1,null,new BehaviorExample.Replay(),new BehaviorPolicy(2,1),new BehaviorVisualPolicy(2)));}
 @Test public void learnedSnapshotRejectsEntryOverflowWithoutChangingOriginal(){BehaviorVisual.Frame a=image(0xff101020,180,600,false);BehaviorExample.Registry registry=new BehaviorExample.Registry().append(new BehaviorExample.Action("a",BehaviorExample.Type.BACK,null,0,false));BehaviorExample.Replay rows=new BehaviorExample.Replay();for(int i=0;i<180;i++){BehaviorExample.Observation o=obs(a,"");rows=rows.append(new BehaviorExample("large"+i,o,"a",o,"DEMONSTRATION",null,true,false));}BehaviorBundle.Snapshot tooLarge=new BehaviorBundle.Snapshot("task",1,registry,rows,new BehaviorPolicy(1,1),new BehaviorVisualPolicy(1));assertThrows(IllegalArgumentException.class,()->BehaviorBundle.write(tooLarge));assertEquals(180,tooLarge.replay.all().size());}
 @Test public void syntheticVisualWorkCostIsReported() throws org.json.JSONException{BehaviorVisual.Frame a=image(0xff101020,180,600,false),b=image(0xffeeeecc,180,600,false);BehaviorExample.Registry registry=new BehaviorExample.Registry().append(new BehaviorExample.Action("a",BehaviorExample.Type.BACK,null,0,false)).append(new BehaviorExample.Action("b",BehaviorExample.Type.FINISH,null,0,false));BehaviorExample.Replay rows=new BehaviorExample.Replay();for(int i=0;i<10;i++)for(int k=0;k<2;k++){BehaviorExample.Observation o=obs(k==0?a:b,"");rows=rows.append(new BehaviorExample("cost"+i+k,o,registry.get(k).id,o,"DEMONSTRATION",null,true,false));}long started=System.nanoTime();BehaviorVisualPolicy learned=new BehaviorVisualPolicy(2).learn(rows,registry,"task",128,()->false);long learnedNs=System.nanoTime()-started;BehaviorVisual.Frame icon=image(0xffeeeeee,180,600,false);BehaviorVisual.Patch patch=BehaviorVisual.patchAt(icon,204,624,1080,1920);long[] scans=new long[5];for(int i=0;i<scans.length;i++){long t=System.nanoTime();BehaviorVisual.resolve(icon,patch,1080,1920);scans[i]=System.nanoTime()-t;}System.out.println("VISUAL_SYNTHETIC_COST "+BehaviorExample.object("rows",20,"outputs",2,"updates",learned.completedSteps(),"training_ns",learnedNs,"scan_ns",new org.json.JSONArray(scans),"full_frame_stored_max_bytes",BehaviorVisual.MAX_WIDTH*BehaviorVisual.MAX_HEIGHT*3,"transient_detail_max_bytes",256*448*3,"max_output_weight_bytes",500L*(BehaviorVisual.INPUT+1)*8));}
 @Test public void unfinishedVisualTeachingCannotGrowPastBundleEntryLimit(){BehaviorExample.Replay original=new BehaviorExample.Replay();BehaviorAndroidSession session=new BehaviorAndroidSession("task",original,null);BehaviorExample.Observation before=obs(image(0xffeeeeee,180,600,false),"");boolean refused=false;for(int n=0;n<200;n++){try{session.stage(before,"image","COMPLETED");session.observeBefore(before);}catch(IllegalStateException capped){refused=true;break;}}assertTrue("완료 전 시각 표본이 제한 없이 누적되었습니다",refused);assertEquals(0,original.all().size());assertEquals(0,session.confirmed().all().size());}
 @Test public void addingVisualActionIdsPreservesExplicitLegacyOutputHead()throws Exception{BehaviorExample.Registry registry=new BehaviorExample.Registry().append(new BehaviorExample.Action("old-a",BehaviorExample.Type.TEXT_TAP,"가",0,false)).append(new BehaviorExample.Action("old-b",BehaviorExample.Type.TEXT_TAP,"나",0,false));BehaviorExample.Replay replay=new BehaviorExample.Replay();for(int i=0;i<2;i++){BehaviorExample.Observation a=BehaviorExampleTest.observation("가"),b=BehaviorExampleTest.observation("나");replay=replay.append(new BehaviorExample("ka"+i,a,"old-a",a,"DEMONSTRATION",null,true,false));replay=replay.append(new BehaviorExample("kb"+i,b,"old-b",b,"DEMONSTRATION",null,true,false));}BehaviorPolicy old=new BehaviorPolicy(2,19).learn(replay,registry,"task",128,8,.05,()->false);BehaviorPolicy expanded=old.appendOutputs(4);BehaviorExample.Observation observed=BehaviorExampleTest.observation("가");double[] expected=old.probabilities(BehaviorFeatures.encode(observed));assertTrue("전역K확장 위험의 실제 재현이 필요합니다",expanded.probabilities(BehaviorFeatures.encode(observed))[0]<expected[0]);java.lang.reflect.Method method;try{method=BehaviorAndroidSession.class.getMethod("legacyProbabilities",BehaviorPolicy.class,BehaviorExample.Replay.class,BehaviorExample.Registry.class,String.class,BehaviorExample.Observation.class);}catch(NoSuchMethodException missing){fail("시각 전용 행동이 구형 글자 모델의 출력 사전으로 섞입니다");return;}BehaviorExample.Registry appended=registry.append(new BehaviorExample.Action("new-a",BehaviorExample.Type.BACK,null,0,false)).append(new BehaviorExample.Action("new-b",BehaviorExample.Type.FINISH,null,0,false));double[] actual=(double[])method.invoke(null,expanded,replay,appended,"task",observed);assertEquals(4,actual.length);assertArrayEquals(expected,Arrays.copyOf(actual,2),0);assertEquals(0,actual[2],0);assertEquals(0,actual[3],0);assertArrayEquals(old.firstLayerParameters(),expanded.firstLayerParameters(),0);assertArrayEquals(old.outputRow(0),expanded.outputRow(0),0);assertArrayEquals(old.outputRow(1),expanded.outputRow(1),0);assertEquals(BehaviorAndroidSession.confident(expected,0),BehaviorAndroidSession.confident(actual,0));BehaviorBundle.Snapshot snapshot=new BehaviorBundle.Snapshot("task",2,appended,replay,expanded,new BehaviorVisualPolicy(4));BehaviorBundle.Snapshot imported=BehaviorBundle.read(new ByteArrayInputStream(BehaviorBundle.write(snapshot)));assertArrayEquals(actual,BehaviorAndroidSession.legacyProbabilities(imported.policy,imported.replay,imported.registry,"task",observed),0);}
 @Test public void uniformRedAndBlueAreNotSpatialImageTargets(){for(int color:new int[]{0xffff0000,0xff0000ff}){int[] pixels=new int[1080*1920];Arrays.fill(pixels,color);BehaviorVisual.Frame frame=BehaviorVisual.Frame.fromArgb(1080,1920,pixels);assertThrows("공간 변화 없는 단색을 이미지로 가르칠 수 없습니다",IllegalArgumentException.class,()->BehaviorVisual.patchAt(frame,200,400,1080,1920));}}
 @Test public void sameImageDifferentWordsRemainDistinctForCombinedLearning(){BehaviorVisual.Frame frame=image(0xffeeeeee,180,600,false);BehaviorExample.Observation a0=BehaviorExampleTest.observation("가"),b0=BehaviorExampleTest.observation("나");BehaviorExample.Observation a=new BehaviorExample.Observation(a0.binding,a0.tokens,"",new double[8],frame),b=new BehaviorExample.Observation(b0.binding,b0.tokens,"",new double[8],frame);assertFalse("시각 학습 입력에서 OCR 글자가 사라졌습니다",Arrays.equals(BehaviorVisual.encode(a),BehaviorVisual.encode(b)));BehaviorExample.Registry registry=new BehaviorExample.Registry().append(new BehaviorExample.Action("a",BehaviorExample.Type.TEXT_TAP,"가",0,false)).append(new BehaviorExample.Action("b",BehaviorExample.Type.TEXT_TAP,"나",0,false));BehaviorExample.Replay replay=new BehaviorExample.Replay();for(int i=0;i<2;i++){replay=replay.append(new BehaviorExample("text-a"+i,a,"a",a,"DEMONSTRATION",null,true,false));replay=replay.append(new BehaviorExample("text-b"+i,b,"b",b,"DEMONSTRATION",null,true,false));}assertEquals("a",BehaviorAndroidSession.supportedAction(replay,"task","demo.app",a));assertEquals("b",BehaviorAndroidSession.supportedAction(replay,"task","demo.app",b));BehaviorVisualPolicy learned=new BehaviorVisualPolicy(2).learn(replay,registry,"task",128,()->false);assertTrue(learned.probabilities(a)[0]>.8);assertTrue(learned.probabilities(b)[1]>.8);}
 @Test public void maximumVisualDictionaryRoundTripsInsideExistingEntryCap(){BehaviorExample.Registry registry=new BehaviorExample.Registry();for(int i=0;i<500;i++)registry=registry.append(new BehaviorExample.Action("max"+i,BehaviorExample.Type.BACK,null,0,false));BehaviorBundle.Snapshot source=new BehaviorBundle.Snapshot("task",1,registry,new BehaviorExample.Replay(),new BehaviorPolicy(500,31),new BehaviorVisualPolicy(500));byte[] bytes=BehaviorBundle.write(source);assertTrue(bytes.length<BehaviorBundle.MAX_BYTES);BehaviorBundle.Snapshot loaded=BehaviorBundle.read(new ByteArrayInputStream(bytes));assertEquals(500,loaded.visualPolicy.outputSize());assertArrayEquals(source.visualPolicy.parameters(),loaded.visualPolicy.parameters(),0);assertEquals(1160,BehaviorVisual.INPUT);}
 @Test public void corruptPackedVisualWeightLengthIsRejected() throws org.json.JSONException{org.json.JSONObject value=new BehaviorVisualPolicy(2).json();String encoded=value.getString("weights_f64");value.put("weights_f64",encoded.substring(4));assertThrows(IllegalArgumentException.class,()->BehaviorVisualPolicy.fromJson(value));}
 @Test public void packedVisualNaNIsRejected() throws org.json.JSONException{org.json.JSONObject value=new BehaviorVisualPolicy(2).json();byte[] bytes=Base64.getDecoder().decode(value.getString("weights_f64"));java.nio.ByteBuffer.wrap(bytes).putLong(0x7ff8000000000000L);value.put("weights_f64",Base64.getEncoder().encodeToString(bytes));assertThrows(IllegalArgumentException.class,()->BehaviorVisualPolicy.fromJson(value));}
 @Test public void sameOcrDifferentImagesProduceDifferentVisualInputs(){assertFalse(Arrays.equals(BehaviorVisual.encode(obs(image(0xff101020,180,600,false),"")),BehaviorVisual.encode(obs(image(0xffeeeecc,180,600,false),""))));assertArrayEquals(BehaviorFeatures.encode(obs(image(0xff101020,180,600,false),"")),BehaviorFeatures.encode(obs(image(0xffeeeecc,180,600,false),"")),0);}
 @Test public void movedSmallIconUsesCurrentPixelsInsteadOfRecordedCoordinates(){BehaviorVisual.Frame a=image(0xffeeeeee,180,600,false),b=image(0xffeeeeee,580,1000,false);BehaviorVisual.Patch p=BehaviorVisual.patchAt(a,204,624,1080,1920);BehaviorVisual.Match found=BehaviorVisual.resolve(b,p,1080,1920);assertTrue(Math.abs((found.left+found.right)/2-604)<30);assertTrue(Math.abs((found.top+found.bottom)/2-1024)<30);}
 @Test public void twoIdenticalIconsAreRejected(){BehaviorVisual.Frame a=image(0xffeeeeee,180,600,false);BehaviorVisual.Patch p=BehaviorVisual.patchAt(a,204,624,1080,1920);assertThrows(IllegalArgumentException.class,()->BehaviorVisual.resolve(image(0xffeeeeee,180,600,true),p,1080,1920));}
 @Test public void blankPatchRejected(){int[] a=new int[1080*1920];Arrays.fill(a,0xffeeeeee);BehaviorVisual.Frame f=BehaviorVisual.Frame.fromArgb(1080,1920,a);assertThrows(IllegalArgumentException.class,()->BehaviorVisual.patchAt(f,200,400,1080,1920));}
 @Test public void visualSupportRequiresTwoDemonstrationsAndSeparatesIdenticalWords(){BehaviorVisual.Frame a=image(0xff101020,180,600,false),b=image(0xffeeeecc,180,600,false);BehaviorExample.Registry r=new BehaviorExample.Registry().append(new BehaviorExample.Action("a",BehaviorExample.Type.BACK,null,0,false)).append(new BehaviorExample.Action("b",BehaviorExample.Type.FINISH,null,0,false));BehaviorExample.Replay replay=replay(r,a,b);assertEquals("a",BehaviorAndroidSession.supportedAction(replay,"task","demo.app",obs(a,"")));assertEquals("b",BehaviorAndroidSession.supportedAction(replay,"task","demo.app",obs(b,"")));}
 @Test public void actualVisualSgdAndBundleRoundTripContinueLearning(){BehaviorVisual.Frame a=image(0xff101020,180,600,false),b=image(0xffeeeecc,180,600,false);BehaviorExample.Registry r=new BehaviorExample.Registry().append(new BehaviorExample.Action("a",BehaviorExample.Type.BACK,null,0,false)).append(new BehaviorExample.Action("b",BehaviorExample.Type.FINISH,null,0,false));BehaviorExample.Replay replay=replay(r,a,b);BehaviorVisualPolicy initial=new BehaviorVisualPolicy(2),trained=initial.learn(replay,r,"task",128,()->false);assertFalse(Arrays.equals(initial.parameters(),trained.parameters()));assertTrue(trained.probabilities(obs(a,""))[0]>.8);assertTrue(trained.probabilities(obs(b,""))[1]>.8);BehaviorBundle.Snapshot s=new BehaviorBundle.Snapshot("task",1,r,replay,new BehaviorPolicy(2,4),trained);BehaviorBundle.Snapshot loaded=BehaviorBundle.read(new ByteArrayInputStream(BehaviorBundle.write(s)));assertArrayEquals(trained.parameters(),loaded.visualPolicy.parameters(),0);assertEquals(256,loaded.visualPolicy.learn(loaded.replay,loaded.registry,"task",128,()->false).completedSteps());assertEquals(128,trained.completedSteps());}
 @Test public void nonPeriodicTwentyPixelPatchMatchesSameAndMovedFrame(){
  int width=256,height=448,left=118,top=214;int[] original=new int[width*height],moved=new int[width*height];Arrays.fill(original,0xffeeeeee);Arrays.fill(moved,0xffeeeeee);Random random=new Random(17);
  // 반복되지 않는 색 경계로 사전검사와 저장 표본의 한 픽셀 차이를 검출합니다.
  for(int y=0;y<20;y++)for(int x=0;x<20;x++){int color=0xff000000|random.nextInt(1<<24);original[(top+y)*width+left+x]=color;moved[(top+60+y)*width+left+40+x]=color;}
  BehaviorVisual.Frame frame=BehaviorVisual.Frame.fromArgb(width,height,original);BehaviorVisual.Patch patch=BehaviorVisual.patchAt(frame,128,224,width,height);assertEquals(20,patch.width);assertEquals(20,patch.height);
  BehaviorVisual.Match same=BehaviorVisual.resolve(frame,patch,width,height);assertEquals(left,same.left);assertEquals(top,same.top);assertEquals(left+20,same.right);assertEquals(top+20,same.bottom);assertEquals(0,same.error,0);
  BehaviorVisual.Match fresh=BehaviorVisual.resolve(BehaviorVisual.Frame.fromArgb(width,height,moved),patch,width,height);assertEquals(left+40,fresh.left);assertEquals(top+60,fresh.top);assertEquals(left+60,fresh.right);assertEquals(top+80,fresh.bottom);assertEquals(0,fresh.error,0);
 }
}
